default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Eventlog\Security' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('WarningLevel', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_log_threshold_audit_event)) {
    Write-Output 'Mismatch: HKLM:\SYSTEM\CurrentControlSet\Services\Eventlog\Security [WarningLevel]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Eventlog\Security')) {
    New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Eventlog\Security' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Eventlog\Security' -Name 'WarningLevel' -Value $ODV_log_threshold_audit_event -PropertyType DWord -Force | Out-Null
exit 0
